 86	    private static String fortressTypeName(String s) {
 87	        if (s.equals(Naming.SNOWMAN)) return "()";
 88	        int left = s.indexOf(Naming.LEFT_OXFORD_CHAR);
 89	        String stem = left == -1 ? s : s.substring(0, left);
 90	        String name = stem.substring(Math.max(stem.lastIndexOf('/'), stem.lastIndexOf('$')) + 1);
 91	        if (stem.startsWith(Naming.RT_VALUES_PKG)) name = name.substring(1); // FZZ32 is ZZ32
 92	        if (left == -1) return name;
 93	        List<String> args = RTHelpers.extractStringParameters(s);
 94	        boolean arrow = stem.equals(Naming.ARROW_TAG) || stem.equals(Naming.ABSTRACT_ARROW);
 95	        int last = arrow ? args.size() - 1 : args.size();
 96	        StringBuilder sb = new StringBuilder();
 97	        for (int i = 0; i < last; i++)
 98	            sb.append(i == 0 ? "" : ",").append(fortressTypeName(args.get(i)));
 99	        String inner = sb.toString();
100	        if (arrow)
101	            return (last == 1 ? inner : "(" + inner + ")") + "->" + fortressTypeName(args.get(last));
102	        if (stem.equals(Naming.TUPLE_TAG) || stem.equals(Naming.CONCRETE_TUPLE))
103	            return "(" + inner + ")";
104	        return name + "[\\" + inner + "\\]";
105	    }
